  "check_code": "import re
import sqlite3
from datetime import datetime
from pathlib import Path


CASE_ID = "CASE-BJ0101-2025-3847"
EVENT_TYPE = "EVIDENCE_EXCHANGE_MINUTES_SIGNED"
EVENT_TIME = datetime(2025, 3, 18, 16, 42)
OPERATOR_ID = "USER-CLERK-LIUY"


def _db_paths(ws):
    root = Path(ws).resolve().parent
    current = root / "system" / "court_case_management" / "state.db"
    backup = root / "system" / "court_case_management" / "state.db.pinned_backup"
    return current, backup


def _connect(path):
    connection = sqlite3.connect(path)
    connection.row_factory = sqlite3.Row
    return connection


def _parse_time(value):
    text = str(value or "").strip().replace("T", " ")
    text = re.sub(r"(?:Z|[+-]\d\d:\d\d)$", "", text).strip()
    for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M", "%Y/%m/%d %H:%M"):
        try:
            return datetime.strptime(text, fmt)
        except ValueError:
            pass
    return None


def _normalized(text):
    return re.sub(r"[^0-9a-z\u4e00-\u9fff]", "", str(text or "").lower())


def _original_ids(current, backup):
    rows = backup.execute("SELECT event_id FROM case_events WHERE case_id = ?", (CASE_ID,)).fetchall()
    return {row["event_id"] for row in rows}


def _new_target_rows(ws):
    current_path, backup_path = _db_paths(ws)
    with _connect(current_path) as current, _connect(backup_path) as backup:
        original_ids = _original_ids(current, backup)
        rows = current.execute(
            "SELECT * FROM case_events WHERE case_id = ? AND event_type = ? AND event_status = '有效'",
            (CASE_ID, EVENT_TYPE),
        ).fetchall()
        return [dict(row) for row in rows if row["event_id"] not in original_ids]


def check_event_core(ws):
    rows = _new_target_rows(ws)
    matching = [
        row for row in rows
        if _parse_time(row["event_time"]) == EVENT_TIME
        and row["operator_id"] == OPERATOR_ID
    ]
    if len(matching) != 1:
        return {
            "score": 0,
            "detail": f"需且仅需新增1条目标案件的有效笔录签署类节点，时间为2025-03-18 16:42、经办口径为{OPERATOR_ID}；当前匹配{len(matching)}条。",
        }
    if len(rows) != 1:
        return {"score": 0, "detail": f"目标案件新增了{len(rows)}条有效笔录签署类节点，存在重复登记。"}
    row = matching[0]
    if any(row.get(key) is not None for key in (
        "evidence_item_id", "evidence_code", "evidence_title", "verification_result", "deadline_id"
    )):
        return {"score": 0, "detail": "归档复核说明节点不应错误关联单项证据或期限。"}
    return {"score": 1, "detail": f"新增节点有效且案件、类型、完成时点、经办人与唯一性均正确：{row['event_id']}。"}


def check_event_notes(ws):
    rows = _new_target_rows(ws)
    if len(rows) != 1:
        return {"score": 0, "detail": "无法唯一定位新增目标节点。"}
    note = _normalized(rows[0].get("notes"))
    checks = {
        "归档或笔录复核完成": (("归档复核" in note or "笔录复核" in note) and ("完成" in note or "通过" in note)),
        "28项": ("28项" in note or "二十八项" in note),
        "328页": ("328页" in note or "三百二十八页" in note),
        "26项核验": ((("26项" in note or "二十六项" in note) and "核验" in note) or (("28项" in note or "二十八项" in note) and "p09" in note and "d12" in note and ("待补核" in note or "待补充核验" in note or ("原件" in note and ("待提交" in note or "尚未闭环" in note or "未闭环" in note or "未完成" in note))) and ("12项" in note or "十二项" in note or "1212" in note) and ("复核" in note or "检查" in note) and ("全部通过" in note or "项通过" in note or "项目通过" in note))),
        "P-09待补核": ("p09" in note and ("待补核" in note or "待补充核验" in note or ("原件" in note and ("待提交" in note or "尚未闭环" in note or "未闭环" in note or "未完成" in note)))),
        "D-12待补核": ("d12" in note and ("待补核" in note or "待补充核验" in note or ("原件" in note and ("待提交" in note or "尚未闭环" in note or "未闭环" in note or "未完成" in note)))),
        "三项书面质证": all(code in note for code in ("p07", "p11", "p14")) and "书面质证" in note and any(word in note for word in ("待提交", "待送交", "待办", "未完成", "提交期限", "送交")),
        "实体认定边界": any(word in note for word in ("不代表", "不等于", "不构成", "并非", "不对", "不作")) and any(word in note for word in ("实体认定", "证据认定", "证明力", "真实性合法性关联性")),
    }
    missing = [name for name, passed in checks.items() if not passed]
    if missing:
        return {"score": 0, "detail": "节点备注缺少或未清楚表达：" + "、".join(missing)}
    return {"score": 1, "detail": "节点备注完整保留复核规模、两项补核、三项书面质证待办及非实体认定边界。"}


def check_historical_events_unchanged(ws):
    current_path, backup_path = _db_paths(ws)
    with _connect(current_path) as current, _connect(backup_path) as backup:
        old_rows = backup.execute(
            "SELECT * FROM case_events WHERE case_id = ? ORDER BY event_id", (CASE_ID,)
        ).fetchall()
        current_by_id = {
            row["event_id"]: tuple(row)
            for row in current.execute("SELECT * FROM case_events WHERE case_id = ?", (CASE_ID,)).fetchall()
        }
        missing = []
        changed = []
        for row in old_rows:
            if row["event_id"] not in current_by_id:
                missing.append(row["event_id"])
            elif tuple(row) != current_by_id[row["event_id"]]:
                changed.append(row["event_id"])
    if missing or changed:
        return {"score": 0, "detail": f"原有事件被删除{missing}或修改{changed}。"}
    return {"score": 1, "detail": "本案原有案件事件均保持不变。"}
